class TestRedirect:

    # Tests: REQ-REDIR-001 | SCENARIO-002
    def test_should_redirect_302_when_valid_code_requested(self, client):
        create_resp = _shorten(client, "https://www.example.com")
        code = create_resp.get_json()["data"]["short_code"]
        resp = client.get(f"/{code}")
        assert resp.status_code == 302
        assert resp.headers["Location"] == "https://www.example.com"

    # Tests: REQ-REDIR-002 | SCENARIO-003
    def test_should_return_404_when_code_does_not_exist(self, client):
        resp = client.get("/xxxxxx")
        assert resp.status_code == 404
        body = resp.get_json()
        assert body["success"] is False
        assert "not found" in body["error"].lower()

    # Tests: REQ-REDIR-003, REQ-EXP-002 | SCENARIO-004
    def test_should_return_410_when_url_is_expired(self, client):
        past = (datetime.now(timezone.utc) - timedelta(hours=1)).isoformat()
        create_resp = _shorten(client, "https://example.com/old", expires_at=past)
        code = create_resp.get_json()["data"]["short_code"]
        resp = client.get(f"/{code}")
        assert resp.status_code == 410
        assert "expired" in resp.get_json()["error"].lower()

    # Tests: REQ-REDIR-001 (future expiry should still redirect)
    def test_should_redirect_when_expiry_is_in_future(self, client):
        future = (datetime.now(timezone.utc) + timedelta(days=1)).isoformat()
        create_resp = _shorten(client, "https://example.com/future", expires_at=future)
        code = create_resp.get_json()["data"]["short_code"]
        resp = client.get(f"/{code}")
        assert resp.status_code == 302


