class TestAnalytics:

    # Tests: REQ-ANAL-001, REQ-ANAL-002 | SCENARIO-002
    def test_should_increment_click_count_on_redirect(self, client):
        code = _shorten(client, "https://analytics.example.com").get_json()["data"]["short_code"]
